/*
 * The star table, unpacked: each star's place as a unit vector (J2000, the
 * equator's frame: x towards right ascension 0, y towards 6 h, z to the north
 * pole), its visual magnitude and its B−V colour, as typed arrays (never
 * thousands of objects). The table itself (stars-data.ts) is generated by
 * scripts/sky/build.ts from Wikidata (public domain). Pure, so unit-tested.
 */

/** How a magnitude and a colour are packed into a byte each: value = byte × step − bias. */
export const MAG_BIAS = 1.5;
export const MAG_STEP = 1 / 32;
export const COLOR_BIAS = 0.5;
export const COLOR_STEP = 0.01;

export interface StarTable {
  count: number;
  /** Unit vectors, three numbers a star (J2000 equatorial). */
  dir: Float32Array;
  /** Visual magnitudes (smaller is brighter), ascending. */
  mag: Float32Array;
  /** B−V: about −0.3 for the bluest, 0.65 for the Sun, 1.5 and more for the reddest. */
  color: Float32Array;
}

/** Unpacks `count` stars from the table's base64 (six bytes each: RA and Dec as 16 bits little-endian, magnitude, colour). */
export function unpackStars(data: string, count: number): StarTable {
  const text = atob(data);
  if (text.length < count * 6) throw new Error("the star table is short");
  const dir = new Float32Array(count * 3);
  const mag = new Float32Array(count);
  const color = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    const o = i * 6;
    const ra = ((text.charCodeAt(o) | (text.charCodeAt(o + 1) << 8)) / 65536) * 2 * Math.PI;
    const dec = ((text.charCodeAt(o + 2) | (text.charCodeAt(o + 3) << 8)) / 65535 - 0.5) * Math.PI;
    const c = Math.cos(dec);
    dir[i * 3] = c * Math.cos(ra);
    dir[i * 3 + 1] = c * Math.sin(ra);
    dir[i * 3 + 2] = Math.sin(dec);
    mag[i] = text.charCodeAt(o + 4) * MAG_STEP - MAG_BIAS;
    color[i] = text.charCodeAt(o + 5) * COLOR_STEP - COLOR_BIAS;
  }
  return { count, dir, mag, color };
}

/** B−V against a tint in linear light: blue-white, white, the Sun's cream, orange, red. A little richer than life, as the world is. */
const TINTS: readonly (readonly [number, number, number, number])[] = [
  [-0.4, 0.6, 0.72, 1],
  [0, 0.8, 0.87, 1],
  [0.35, 1, 0.97, 0.92],
  [0.7, 1, 0.9, 0.72],
  [1.1, 1, 0.76, 0.5],
  [1.6, 1, 0.6, 0.34],
  [2.1, 1, 0.48, 0.26],
];

/** A star's colour (linear RGB, its brightest channel 1) from its B−V, into `out`. */
export function starColor(bv: number, out: [number, number, number]): [number, number, number] {
  let i = 0;
  while (i < TINTS.length - 2 && TINTS[i + 1]![0] <= bv) i++;
  const a = TINTS[i]!;
  const b = TINTS[i + 1]!;
  const t = Math.max(0, Math.min(1, (bv - a[0]) / (b[0] - a[0])));
  out[0] = a[1] + (b[1] - a[1]) * t;
  out[1] = a[2] + (b[2] - a[2]) * t;
  out[2] = a[3] + (b[3] - a[3]) * t;
  return out;
}

/**
 * How brightly a star of a magnitude is drawn, 0..1. Real stars span a
 * thousandfold in light; a screen can't, so the scale is compressed (a
 * magnitude is a factor of 1.46 here, not 2.512), the brightest held at 1.
 */
export function starBrightness(magnitude: number): number {
  return Math.min(1, 0.95 * Math.exp(-0.38 * (magnitude + 1)));
}

/** How large it's drawn (the radius of its glint, radians on the sky): the bright ones larger, the faintest still a pixel or two across. */
export function starSize(magnitude: number): number {
  return (0.085 + 0.15 * Math.min(1, Math.exp(-0.42 * (magnitude + 1)))) * (Math.PI / 180);
}
